import 'dart:async';import 'package:geolocator/geolocator.dart';class SharedLocation {  final String id;  final String userId;  final String userName;  final double latitude;  final double longitude;  final DateTime timestamp;  final Duration? expiresIn;  SharedLocation({    required this.id,    required this.userId,    required this.userName,    required this.latitude,    required this.longitude,    required this.timestamp,    this.expiresIn,  });  bool get isExpired {    if (expiresIn == null) return false;    return DateTime.now().isAfter(timestamp.add(expiresIn!));  }  Map<String, dynamic> toJson() => {        'id': id,        'userId': userId,        'userName': userName,        'latitude': latitude,        'longitude': longitude,        'timestamp': timestamp.toIso8601String(),        'expiresIn': expiresIn?.inMinutes,      };  factory SharedLocation.fromJson(Map<String, dynamic> json) => SharedLocation(        id: json['id'],        userId: json['userId'],        userName: json['userName'],        latitude: json['latitude'],        longitude: json['longitude'],        timestamp: DateTime.parse(json['timestamp']),        expiresIn: json['expiresIn'] != null            ? Duration(minutes: json['expiresIn'])            : null,      );}class LocationShareService {  static const Duration _updateInterval = Duration(seconds: 10);  final _locationUpdateController =      StreamController<SharedLocation>.broadcast();  Stream<SharedLocation> get locationUpdates =>      _locationUpdateController.stream;  Timer? _updateTimer;  Position? _currentPosition;  bool _isSharing = false;  String? _myUserId;  String? _myUserName;  bool get isSharing => _isSharing;  Future<bool> checkPermissions() async {    bool serviceEnabled = await Geolocator.isLocationServiceEnabled();    if (!serviceEnabled) return false;    LocationPermission permission = await Geolocator.checkPermission();    if (permission == LocationPermission.denied) {      permission = await Geolocator.requestPermission();      if (permission == LocationPermission.denied) return false;    }    if (permission == LocationPermission.deniedForever) return false;    return true;  }  Future<Position?> getCurrentLocation() async {    final hasPermission = await checkPermissions();    if (!hasPermission) return null;    try {      _currentPosition = await Geolocator.getCurrentPosition(        desiredAccuracy: LocationAccuracy.high,      );      return _currentPosition;    } catch (e) {      return null;    }  }  void startSharing(String userId, String userName, {Duration? duration}) {    _myUserId = userId;    _myUserName = userName;    _isSharing = true;    _updateTimer = Timer.periodic(_updateInterval, (_) => _updateLocation());    _updateLocation();  }  void stopSharing() {    _isSharing = false;    _updateTimer?.cancel();    _updateTimer = null;  }  Future<void> _updateLocation() async {    final position = await getCurrentLocation();    if (position == null || _myUserId == null || _myUserName == null) return;    final location = SharedLocation(      id: '${_myUserId}_${DateTime.now().millisecondsSinceEpoch}',      userId: _myUserId!,      userName: _myUserName!,      latitude: position.latitude,      longitude: position.longitude,      timestamp: DateTime.now(),    );    _locationUpdateController.add(location);  }  SharedLocation createLocationUpdate(      Position position, String userId, String userName) {    return SharedLocation(      id: '${userId}_${DateTime.now().millisecondsSinceEpoch}',      userId: userId,      userName: userName,      latitude: position.latitude,      longitude: position.longitude,      timestamp: DateTime.now(),    );  }  String formatDistance(double lat1, double lon1, double lat2, double lon2) {    final distance = Geolocator.distanceBetween(lat1, lon1, lat2, lon2);    if (distance < 1000) {      return '${distance.round()} m';    } else {      return '${(distance / 1000).toStringAsFixed(1)} km';    }  }  void dispose() {    stopSharing();    _locationUpdateController.close();  }}